import re
import unittest
from calc import evaluate

GOOD = ["-2**2", "2**-1", "2**3**2", "-(-3)", "--3", "7//2", "-7//2", "7%-3", "6/3", "1e3", ".5+2.", "2.5e-1*4",
        "(1+2)*(3+4)**2", "2 ** 3 ** 0", "10-4-3", "100/10/5", "-2**-2", "+-+3", "2*-3", "1 - -1", "( ( 4 ) )",
        "3*(2+(4-1))**2//5", "2**3", "8-3*2+1", "  42  ", "1+2*3-4/2", "-3**2+10", "2*(3+4)*5", "17%5*2", "1.5//0.4"]
BAD = ["", "   ", "2 +", "(1", "1 2", "2 ** * 3", "x+1", "2 $ 3", "()", "1)", "1..2", "1e", "*3", "2 3 +", "1 + (2", "abs(1)"]
ZERO = ["1/0", "5%0", "4//(2-2)", "1/(3-3.0)"]


class H(unittest.TestCase):
    def test_values_and_types(self):
        for text in GOOD:
            want = eval(text)
            got = evaluate(text)
            self.assertEqual(got, want, text)
            self.assertIs(type(got), type(want), text)

    def test_invalid(self):
        for text in BAD:
            with self.assertRaises(ValueError, msg=repr(text)):
                evaluate(text)

    def test_zero_division(self):
        for text in ZERO:
            with self.assertRaises(ZeroDivisionError, msg=text):
                evaluate(text)

    def test_parses_by_itself(self):
        src = open("calc.py").read()
        self.assertIsNone(re.search(r"(?<![.\w])(eval|exec|compile)\s*\(|^\s*(import|from)\s+ast\b", src, re.M))


if __name__ == "__main__":
    unittest.main()
